with enriched as (select *, lag(discount_pct, 1) over (order by ends_on asc, id asc) prev_discount_pct, rank() over (partition by promo_code order by discount_pct asc) discount_pct_rank from promotions), scored as (select *, ntile(5) over w_running discount_pct_rank_bucket, avg(discount_pct) over (order by starts_on asc, id asc rows between 5 preceding and 1 preceding) discount_pct_avg_5_prior, row_number() over (partition by channel order by discount_pct asc, id asc) seq_no, avg(discount_pct_rank) over (order by ends_on asc, id asc rows between 6 preceding and 1 preceding) discount_pct_rank_avg_6_prior, sum(discount_pct) over (partition by promo_code, channel order by ends_on asc, id asc rows between unbounded preceding and current row) running_discount_pct from enriched window w_running as (order by discount_pct_rank asc, id asc)), ranked as (select id, channel, discount_pct, prev_discount_pct, discount_pct_rank, discount_pct_avg_5_prior from (select *, row_number() over (partition by channel, promo_code order by ends_on asc, id asc) as rn from scored) x where rn = 1), valid as (select id, channel, discount_pct, prev_discount_pct, discount_pct_rank, discount_pct_avg_5_prior, ceil(discount_pct_rank) discount_pct_rank_whole, initcap(trim(channel)) channel_title from ranked where channel <> 'partner'), latest as (select *, row_number() over (partition by channel order by discount_pct_rank_whole desc nulls first, id asc) as row_num from valid qualify row_num = 1), matched_keys as (select id, channel from latest intersect select id, channel from promotions where promo_code in ('VIP', 'BUNDLE')), reconciled as (select s.* from latest s inner join matched_keys k on s.id = k.id and s.channel = k.channel) select id, channel, prev_discount_pct, discount_pct_rank, discount_pct_avg_5_prior, discount_pct_rank_whole, row_num from reconciled order by channel desc nulls first;
